const struct mh_desc *mh_desc_for_game(u8 game_id)
{
	unsigned i;

	for (i = 0; i < sizeof(mh_descs) / sizeof(mh_descs[0]); i++) {
		if (mh_descs[i].game_id == game_id) return &mh_descs[i];
	}
	return NULL;
}
